___CSS_LOADER_EXPORT___.push([module.id, `.query-graph {
  --qg-graph-toolbar-button-size: 2em;
  --xy-edge-stroke: var(--qg-border);
  --xy-edge-stroke-selected: var(--qg-text-muted);
  --xy-minimap-background-color: var(--qg-surface);
  --xy-minimap-mask-background-color: color-mix(in srgb, var(--qg-minimap-mask-color) 60%, transparent);
  --xy-minimap-node-background-color: var(--qg-text-muted);

  & .react-flow__pane {
    background: var(--qg-canvas);
  }

  & .react-flow__handle {
    width: 6px;
    height: 6px;
    background-color: transparent;
    border: none;
    pointer-events: none;
  }

  & .react-flow__pane,
  & .react-flow__edge,
  & .react-flow__node {
    cursor: default;
  }

  & .react-flow__edge-textbg {
    opacity: .7;
    fill: var(--qg-surface);
    stroke: var(--qg-edge-label-border);
  }

  & .react-flow__edge-text {
    font-size: .6em;
    fill: currentColor;
  }

  & .react-flow__edge.qg-label-highlighted .react-flow__edge-text {
    fill: var(--qg-accent-2);
  }

  & .react-flow__edge.qg-crosslink {
    & .react-flow__edge-path {
      stroke: var(--qg-border);
      stroke-dasharray: 4 4;
      transition-property: stroke, stroke-width, stroke-dasharray;
      transition-duration: .5s;
    }

    &:hover .react-flow__edge-path,
    &:focus .react-flow__edge-path {
      stroke: var(--qg-accent-3);
      stroke-width: 1.5px;
      stroke-dasharray: 6 2;
    }
  }

  & .react-flow__minimap-node {
    transition: stroke .2s;
    vector-effect: non-scaling-stroke;

    &.qg-highlighted {
      stroke: var(--qg-focus);
      stroke-width: 3px;
    }
  }

  & .qg-graph-toolbar {
    display: flex;
    flex-direction: column;

    & > .qg-icon-button-wrapper {
      display: flex;
    }

    & > .qg-icon-button-wrapper + .qg-icon-button-wrapper {
      border-block-start: 1px solid var(--qg-border);
    }

    & .qg-icon-button {
      width: var(--qg-graph-toolbar-button-size);
      height: var(--qg-graph-toolbar-button-size);
      padding: 0.425em;
      border: 0;
      border-radius: 0;
      background: transparent;

      & svg {
        width: 100%;
        height: 100%;
        fill: currentColor;
        stroke: none;
      }
    }

    & > .qg-icon-button-wrapper:first-child .qg-icon-button {
      border-start-start-radius: var(--qg-panel-inner-radius);
      border-start-end-radius: var(--qg-panel-inner-radius);
    }

    & > .qg-icon-button-wrapper:last-child .qg-icon-button {
      border-end-start-radius: var(--qg-panel-inner-radius);
      border-end-end-radius: var(--qg-panel-inner-radius);
    }

    & .qg-icon-button:hover:not(:disabled) {
      background: var(--qg-surface-hover);
    }

    /* Open toolbar tooltips into the canvas rather than below the viewport. */
    & .qg-icon-button-tooltip {
      inset-block-start: 50%;
      inset-inline: 100% auto;
      padding-block-start: 0;
      padding-inline-start: 0.35em;
      transform: translateY(-50%);
    }
  }
}

@supports (anchor-scope: --qg-icon-button-anchor) and (position-area: inline-end) {
  .query-graph .qg-graph-toolbar .qg-icon-button-tooltip {
    inset: auto;
    position-area: inline-end center;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .query-graph .react-flow__edge.qg-crosslink .react-flow__edge-path {
    transition: stroke .2s;
  }
}

@media (forced-colors: active) {
  .query-graph .react-flow__minimap-node.qg-highlighted {
    stroke: Highlight;
  }
}
